structureCode.vanilla:
import { createMenubar } from '@/components/ui/menubar';

const bar = createMenubar([
  {
    label: 'Arquivo',
    items: [
      { label: 'Novo', shortcut: 'Ctrl+N' },
      { label: 'Abrir', shortcut: 'Ctrl+O' },
      { type: 'separator' },
      {
        type: 'submenu',
        label: 'Exportar',
        items: [{ label: 'PDF' }, { label: 'CSV' }],
      },
    ],
  },
  {
    label: 'Editar',
    items: [{ label: 'Desfazer', shortcut: 'Ctrl+Z' }],
  },
]);

document.body.appendChild(bar);

extensibilityCode.vanilla:
// Menu aberto ao montar, sem dar a volta do último gatilho para o primeiro
const bar = createMenubar(menus, {
  loop: false,
  defaultOpen: 0,
  side: 'bottom',
  align: 'start',
});

customizationCode.web:
/* Override de cor da bar */
[data-slot='menubar'] {
  background-color: hsl(var(--card));
  border-bottom: 1px solid hsl(var(--border));
}

